# owner: platform
"""Find the stretches of opening hours nobody covers."""

from typing import List

from hourglass.parsing import format_span
from hourglass.models import Span
from hourglass.merging import merge_spans

def _check_inside(worked: List[Span], hours: Span):
    for span in worked:
        if span.start < hours.start or span.end > hours.end:
            name = format_span(span)
            raise ValueError(f"{name} is outside hours")

def _uncovered(merged: List[Span], hours: Span):
    edges = [hours.start]
    for span in merged:
        edges += [span.start, span.end]
    edges.append(hours.end)
    pairs = zip(edges[::2], edges[1::2])
    return [Span(begin, stop)
            for begin, stop in pairs if begin < stop]

def _label(gap: Span) -> str:
    return f"gap {format_span(gap)} ({gap.minutes} min)"

def find_gaps(
    worked: List[Span], hours: Span
) -> List[str]:
    """One label per gap; ValueError if outside hours."""
    _check_inside(worked, hours)
    merged = merge_spans(worked)
    gaps = _uncovered(merged, hours)
    return [_label(gap) for gap in gaps]
